INSERT INTO questions (direction, skill, question, options, correct_answer) VALUES
('frontend', 'HTML', 'Səhifədə 3 dənə <h1> var. SEO və ekran oxuyucular baxımından ən yaxşı təcrübə hansıdır?', '["Bütün başlıqları <div class=\"title\"> ilə əvəz etmək", "Artıq <h1>-ləri display: none ilə gizlətmək", "Hər bölmə üçün ayrıca <h1> saxlamaq daha yaxşıdır", "Bir <h1> saxlayıb, qalanlarını <h2>–<h6> ilə iyerarxik qurmaq"]', 'Bir <h1> saxlayıb, qalanlarını <h2>–<h6> ilə iyerarxik qurmaq'),
('frontend', 'HTML', 'Şəkil yalnız dekorativdirsə (heç bir məna daşımırsa), alt atributu necə yazılmalıdır?', '["alt=\"\" (boş dəyər)", "alt=\"decorative image\"", "alt=\"şəkil\"", "alt atributu ümumiyyətlə yazılmamalıdır"]', 'alt="" (boş dəyər)'),
('frontend', 'HTML', 'Formadakı düyməyə basanda səhifə yenilənir. <button> formanın içindədir və type atributu yazılmayıb. Səbəb nədir?', '["<button>-un default type dəyəri \"submit\"-dir", "Brauzerin xətasıdır", "JavaScript faylı yüklənməyib", "Formanın method atributu yazılmayıb"]', '<button>-un default type dəyəri "submit"-dir'),
('frontend', 'HTML', 'Ekran oxuyucu istifadəçilərinin səhifənin əsas məzmununa birbaşa keçməsi üçün hansı element nəzərdə tutulub?', '["<aside>", "<div id=\"content\">", "<main>", "<section>"]', '<main>'),
('frontend', 'HTML', '<input type="email" required> olan forma göndərilir. Hansı fikir doğrudur?', '["Brauzer yoxlaması kifayətdir, server yoxlaması lazım deyil", "required atributu yalnız type=\"text\" ilə işləyir", "Yoxlama yalnız serverdə aparılır", "Brauzer formatı yoxlayır, amma server tərəfində də yoxlama mütləqdir"]', 'Brauzer formatı yoxlayır, amma server tərəfində də yoxlama mütləqdir'),
('frontend', 'HTML', 'Link target="_blank" ilə yeni tabda açılır. Təhlükəsizlik üçün hansı atribut da əlavə olunmalıdır?', '["referrerpolicy=\"origin\"", "rel=\"external nofollow\"", "rel=\"noopener noreferrer\"", "crossorigin=\"anonymous\""]', 'rel="noopener noreferrer"'),
('frontend', 'CSS', 'box-sizing: border-box olan, width: 200px, padding: 20px və border: 5px olan elementin ekrandakı ümumi eni nə qədərdir?', '["225px", "240px", "200px", "250px"]', '200px'),
('frontend', 'CSS', 'Mobil ekranda flex konteynerdəki kartlar sıxılır və kənara daşır. Ən düzgün həll hansıdır?', '["Konteynerə flex-wrap: wrap əlavə etmək", "Şrift ölçüsünü kiçiltmək", "Konteynerə overflow: hidden yazmaq", "Kartlara position: absolute vermək"]', 'Konteynerə flex-wrap: wrap əlavə etmək'),
('frontend', 'CSS', '<p id="intro"> elementi .card-ın içindədir. .card p { color: red } və #intro { color: blue } qaydaları var. Mətn hansı rəngdə olacaq?', '["Qırmızı, çünki seçici iki hissədən ibarətdir", "Mavi, çünki id seçicisinin spesifikliyi daha yüksəkdir", "Qırmızı, çünki class həmişə üstündür", "Brauzerdən asılıdır"]', 'Mavi, çünki id seçicisinin spesifikliyi daha yüksəkdir'),
('frontend', 'CSS', 'Elementi həm üfüqi, həm də şaquli mərkəzləşdirməyin ən qısa müasir yolu hansıdır?', '["float: center;", "text-align: center; vertical-align: middle;", "Valideynə display: grid; place-items: center;", "Yalnız margin: auto;"]', 'Valideynə display: grid; place-items: center;'),
('frontend', 'CSS', 'position: sticky işləmir. Ən çox rast gəlinən səbəb hansıdır?', '["Elementin display dəyəri block-dur", "top (və ya bottom) dəyəri verilməyib", "z-index yazılmayıb", "Element <div>-dir"]', 'top (və ya bottom) dəyəri verilməyib'),
('frontend', 'CSS', '1rem nəyə bərabərdir?', '["Bütün brauzerlərdə həmişə 20px-ə", "Valideyn elementin font-size dəyərinə", "Kök (html) elementin font-size dəyərinə", "Ekran eninin 1%-nə"]', 'Kök (html) elementin font-size dəyərinə'),
('frontend', 'JavaScript', 'const a = [1, 2]; const b = a; b.push(3); — bu koddan sonra a.length nəyə bərabərdir?', '["3", "Xəta: const dəyişdirilə bilməz", "2", "undefined"]', '3'),
('frontend', 'JavaScript', 'console.log(0.1 + 0.2 === 0.3) nə çıxarır?', '["NaN", "undefined", "true", "false"]', 'false'),
('frontend', 'JavaScript', 'for (var i = 0; i < 3; i++) { setTimeout(() => console.log(i), 0) } — konsola nə çıxacaq?', '["undefined üç dəfə", "0 0 0", "0 1 2", "3 3 3"]', '3 3 3'),
('frontend', 'JavaScript', 'Hansı ifadə true qaytarır?', '["null == undefined", "[] === []", "null === undefined", "NaN === NaN"]', 'null == undefined'),
('frontend', 'JavaScript', 'Siyahıda 1000 element var və hər birinə ayrıca click listener əlavə olunub. Daha səmərəli yol hansıdır?', '["Event delegation: listener-i valideyn elementə əlavə etmək", "Hər elementə inline onclick atributu yazmaq", "Listener-ləri requestAnimationFrame içində əlavə etmək", "Hər elementə addEventListener ilə { once: true } vermək"]', 'Event delegation: listener-i valideyn elementə əlavə etmək'),
('frontend', 'JavaScript', 'fetch() serverdən 404 cavabı alır. Nə baş verir?', '["Promise reject olur və catch bloku işləyir", "response.status 200, response.ok isə false olur", "Promise heç vaxt tamamlanmır (pending qalır)", "Promise resolve olur, response.ok isə false olur"]', 'Promise resolve olur, response.ok isə false olur'),
('frontend', 'React', 'count = 0-dır. Bir klikdə setCount(count + 1); setCount(count + 1); çağırılır. Yeni dəyər nə olacaq?', '["Xəta verəcək", "0", "1", "2"]', '1'),
('frontend', 'React', 'Siyahını render edərkən key olaraq massivin indeksindən istifadə etmək nə vaxt problem yaradır?', '["Yalnız komponent class kimi yazıldıqda və state istifadə edildikdə", "Elementlər silinəndə, əlavə olunanda və ya sırası dəyişəndə", "Yalnız siyahıda 100-dən çox element olub performans düşəndə", "Heç vaxt, çünki React indeksləri avtomatik unikal açara çevirir"]', 'Elementlər silinəndə, əlavə olunanda və ya sırası dəyişəndə'),
('frontend', 'React', 'useEffect(() => { ... }, []) nə vaxt işləyir?', '["Hər render-dən sonra, dəyişiklik olsa da, olmasa da", "Yalnız komponent ekrandan silinəndə", "Yalnız komponent ilk dəfə render olunanda", "Yalnız state dəyişəndən sonra"]', 'Yalnız komponent ilk dəfə render olunanda'),
('frontend', 'React', 'Komponent useEffect içində setInterval başladır, komponent silinəndən sonra da interval işləyir. Həll nədir?', '["useEffect-dən clearInterval çağıran cleanup funksiyası qaytarmaq", "setInterval-ı useEffect-dən çıxarıb komponentin gövdəsinə köçürmək", "Komponenti React.memo ilə bükərək yenidən render-i dayandırmaq", "Interval ID-sini useState-də saxlayıb hər render-də yeniləmək"]', 'useEffect-dən clearInterval çağıran cleanup funksiyası qaytarmaq'),
('frontend', 'React', 'Input-un dəyəri state-də saxlanılır və onChange ilə yenilənir. Bu yanaşma necə adlanır?', '["Controlled component", "Uncontrolled component", "Pure component", "Higher-order component"]', 'Controlled component'),
('frontend', 'React', 'Eyni məlumat (məs. login olmuş istifadəçi) 10 fərqli komponentdə lazımdır. Prop drilling-dən qaçmaq üçün nə istifadə olunur?', '["Context API (və ya state kitabxanası)", "Hər komponentdə ayrıca fetch etmək", "Hər komponentdə useEffect ilə localStorage oxumaq", "Məlumatı qlobal window dəyişənində saxlamaq"]', 'Context API (və ya state kitabxanası)'),
('frontend', 'Git', 'Hələ push etmədiyin son commit-in mesajını dəyişmək üçün hansı əmr istifadə olunur?', '["git reset --hard", "git commit --amend", "git revert HEAD", "git push --force"]', 'git commit --amend'),
('frontend', 'Git', 'Komanda üzvlərinin artıq pull etdiyi commit-i geri qaytarmağın təhlükəsiz yolu hansıdır?', '["git checkout <commit>", "git revert <commit>", "git reset --hard <commit>, sonra git push --force", "Faylları əllə silmək"]', 'git revert <commit>'),
('frontend', 'Git', 'git pull-dan sonra "CONFLICT" mesajı çıxır. Nə etmək lazımdır?', '["git stash edib pull-u təkrarlamaq, konflikt yox olacaq", "git push --force ilə öz versiyanı göndərmək", "Repo-nu silib yenidən clone edib dəyişiklikləri təkrar yazmaq", "Konfliktli hissəni əllə həll edib git add və git commit etmək"]', 'Konfliktli hissəni əllə həll edib git add və git commit etmək'),
('frontend', 'Git', '.env faylı səhvən commit və push olunub. Ən düzgün addım hansıdır?', '["Repo-nu private etmək kifayətdir, daha heç kim fayla baxa bilməz", "Şifrə və açarları dərhal dəyişmək, faylı .gitignore-a əlavə edib repodan çıxarmaq", "Faylı silib yeni commit etmək kifayətdir, son versiyada görünməyəcək", "git commit --amend ilə faylı son commit-dən çıxarıb yenidən push etmək"]', 'Şifrə və açarları dərhal dəyişmək, faylı .gitignore-a əlavə edib repodan çıxarmaq'),
('frontend', 'Git', 'git fetch ilə git pull arasındakı fərq nədir?', '["fetch dəyişiklikləri yükləyir, amma birləşdirmir; pull həm yükləyir, həm birləşdirir", "pull dəyişiklikləri yükləyir, amma birləşdirmir; fetch həm yükləyir, həm birləşdirir", "Heç bir fərq yoxdur, fetch sadəcə pull əmrinin köhnə adıdır", "fetch yalnız yeni branch-ları, pull isə yalnız mövcud branch-ları yeniləyir"]', 'fetch dəyişiklikləri yükləyir, amma birləşdirmir; pull həm yükləyir, həm birləşdirir'),
('frontend', 'Git', 'Komandada yeni funksiya üzərində işləyərkən ən yaxşı təcrübə hansıdır?', '["Feature branch yaratmaq və Pull Request ilə birləşdirmək", "Birbaşa main-ə kiçik commit-lərlə push etmək", "Hər funksiya üçün ayrıca fork və ya repo yaratmaq", "Kodu bitənə qədər lokalda saxlayıb sonda bir commit etmək"]', 'Feature branch yaratmaq və Pull Request ilə birləşdirmək'),
('backend', 'Node.js', 'Server böyük faylı fs.readFileSync ilə oxuyarkən digər sorğulara cavab vermir. Səbəb nədir?', '["Node.js eyni anda yalnız bir fayl aça bilir", "Sinxron əməliyyat event loop-u bloklayır", "Serverdə RAM çatışmır", "fs modulu köhnəlib"]', 'Sinxron əməliyyat event loop-u bloklayır'),
('backend', 'Node.js', 'console.log(1); setTimeout(() => console.log(2), 0); Promise.resolve().then(() => console.log(3)); console.log(4); — çıxış sırası necədir?', '["1 4 3 2", "1 3 4 2", "1 2 3 4", "1 4 2 3"]', '1 4 3 2'),
('backend', 'Node.js', 'Promise.all([p1, p2, p3]) çağırılır və p2 reject olur. Nə baş verir?', '["p2 avtomatik təkrar işə salınır", "Hamısı null qaytarır", "p2 nəzərə alınmır, qalanların nəticəsi qaytarılır", "Promise.all dərhal reject olur"]', 'Promise.all dərhal reject olur'),
('backend', 'Node.js', 'package.json-da dependencies ilə devDependencies arasındakı fərq nədir?', '["devDependencies production build-ə avtomatik daxil edilir", "dependencies yalnız lokalda, devDependencies isə serverdə yüklənir", "devDependencies yalnız inkişaf və test zamanı lazımdır", "Fərq yoxdur, sadəcə paketləri qruplaşdırmaq üçündür"]', 'devDependencies yalnız inkişaf və test zamanı lazımdır'),
('backend', 'Node.js', 'process.env.PORT nədir?', '["package.json faylındakı \"port\" sahəsindən oxunan dəyər", "Node.js quraşdırılarkən təyin olunan standart port dəyəri", "Mühit dəyişənindən (environment variable) gələn port dəyəri", "Brauzerin serverə qoşulmaq üçün istifadə etdiyi port"]', 'Mühit dəyişənindən (environment variable) gələn port dəyəri'),
('backend', 'Node.js', 'Eyni modul ikinci dəfə require ediləndə nə baş verir?', '["Xəta verir", "Keşdən (cache) eyni obyekt qaytarılır", "Modul yenidən icra olunur", "Modulun yeni nüsxəsi yaradılır"]', 'Keşdən (cache) eyni obyekt qaytarılır'),
('backend', 'Express', 'Middleware nə next() çağırır, nə də cavab göndərir. Nə baş verir?', '["Sorğu cavabsız qalır (asılı qalır)", "Server dayanır", "Növbəti middleware yenə də işləyir", "Express avtomatik 200 qaytarır"]', 'Sorğu cavabsız qalır (asılı qalır)'),
('backend', 'Express', 'Express-də xəta idarə edən (error-handling) middleware-in imzası necədir?', '["(req, res)", "(err, req, res, next)", "(error)", "(req, res, next)"]', '(err, req, res, next)'),
('backend', 'Express', 'POST sorğusunun JSON body-si req.body-də undefined gəlir. Ən çox ehtimal olunan səbəb nədir?', '["Serverdə cors middleware qoşulmayıb", "Route app.post əvəzinə app.get ilə yazılıb", "Cavab res.json() əvəzinə res.send() ilə qaytarılıb", "app.use(express.json()) əlavə olunmayıb"]', 'app.use(express.json()) əlavə olunmayıb'),
('backend', 'Express', 'app.get(''/users/:id'') route-u app.get(''/users/me'')-dən əvvəl yazılıb. /users/me sorğusu hansı route-a düşür?', '["/users/me route-una, çünki daha dəqiq route üstündür", "Express konflikt görüb 404 qaytarır", "Hər iki route ardıcıl olaraq işləyir", "/users/:id route-una, id = \"me\" olur"]', '/users/:id route-una, id = "me" olur'),
('backend', 'Express', 'Frontend localhost:5173-dən localhost:5000-ə sorğu göndərir və brauzer CORS xətası verir. Düzgün həll hansıdır?', '["Frontend-i də 5000 portunda işə salmaq", "Sorğunu fetch əvəzinə axios ilə göndərmək", "Serverdə cors ilə 5173 mənbəyinə icazə vermək", "Frontend-də sorğuya mode: ''no-cors'' əlavə etmək"]', 'Serverdə cors ilə 5173 mənbəyinə icazə vermək'),
('backend', 'Express', 'Express 4-də async route-da atılan xəta mərkəzi error handler-ə necə çatdırılır?', '["try/catch ilə tutub next(err) çağırmaqla", "Avtomatik çatır, heç nə etmək lazım deyil", "process.exit() ilə", "res.end(err) ilə"]', 'try/catch ilə tutub next(err) çağırmaqla'),
('backend', 'SQL', 'Heç sifariş verməmiş istifadəçiləri tapmaq üçün düzgün sorğu hansıdır?', '["SELECT * FROM users WHERE orders = 0", "SELECT * FROM orders WHERE user_id IS NULL", "SELECT u.* FROM users u LEFT JOIN orders o ON o.user_id = u.id WHERE o.id IS NULL", "SELECT * FROM users INNER JOIN orders ON orders.user_id = users.id"]', 'SELECT u.* FROM users u LEFT JOIN orders o ON o.user_id = u.id WHERE o.id IS NULL'),
('backend', 'SQL', 'WHERE ilə HAVING arasındakı fərq nədir?', '["HAVING qruplaşdırmadan əvvəl sətirləri, WHERE isə qruplaşdırmadan sonra qrupları filtrləyir", "WHERE qruplaşdırmadan əvvəl sətirləri, HAVING isə qruplaşdırmadan sonra qrupları filtrləyir", "WHERE yalnız mətn sütunlarını, HAVING isə yalnız rəqəm sütunlarını filtrləyir", "Fərq yoxdur, HAVING sadəcə WHERE-in JOIN ilə işləyən versiyasıdır"]', 'WHERE qruplaşdırmadan əvvəl sətirləri, HAVING isə qruplaşdırmadan sonra qrupları filtrləyir'),
('backend', 'SQL', 'Bir-biri ilə əlaqəli iki INSERT-dən biri uğursuz olsa, hər ikisi ləğv olunmalıdır. Nə istifadə olunur?', '["Hər iki sorğunu bir VIEW-in içində birləşdirmək", "Tranzaksiya (BEGIN / COMMIT / ROLLBACK)", "İkinci INSERT-i TRIGGER ilə avtomatik işə salmaq", "Hər iki cədvələ FOREIGN KEY əlavə etmək"]', 'Tranzaksiya (BEGIN / COMMIT / ROLLBACK)'),
('backend', 'SQL', '1 milyon sətirlik users cədvəlində email ilə axtarış yavaşdır. Ən təsirli həll hansıdır?', '["Sorğudan LIMIT-i çıxarmaq", "SELECT * əvəzinə SELECT email yazmaq", "email sütununa indeks yaratmaq", "Cədvəli iki cədvələ bölmək"]', 'email sütununa indeks yaratmaq'),
('backend', 'SQL', 'COUNT(*) ilə COUNT(sütun) arasındakı fərq nədir?', '["COUNT(*) yalnız unikal dəyərləri sayır", "COUNT(sütun) həmişə daha çox sətir qaytarır", "COUNT(sütun) NULL dəyərləri saymır", "Heç bir fərq yoxdur"]', 'COUNT(sütun) NULL dəyərləri saymır'),
('backend', 'SQL', 'Bir sifarişdə çoxlu məhsul, bir məhsulda isə çoxlu sifariş ola bilər. Bu əlaqə necə modelləşdirilir?', '["İki cədvəli bir cədvəldə birləşdirmək", "Aralıq cədvəl ilə (məs. order_items: order_id, product_id)", "orders cədvəlinə products sütunu əlavə edib vergüllə yazmaq", "Hər məhsul üçün ayrıca cədvəl yaratmaq"]', 'Aralıq cədvəl ilə (məs. order_items: order_id, product_id)'),
('backend', 'REST API', 'Yeni resurs uğurla yaradıldıqda hansı status kodunu qaytarmaq daha düzgündür?', '["204 No Content", "201 Created", "302 Found", "200 OK"]', '201 Created'),
('backend', 'REST API', 'İstifadəçi login olub, amma başqasının məlumatına baxmağa icazəsi yoxdur. Hansı status kodu uyğundur?', '["400 Bad Request", "500 Internal Server Error", "401 Unauthorized", "403 Forbidden"]', '403 Forbidden'),
('backend', 'REST API', 'Hansı HTTP metodu idempotentdir (eyni sorğunu təkrar göndərmək nəticəni dəyişmir)?', '["Yalnız PATCH", "Heç biri", "POST", "PUT"]', 'PUT'),
('backend', 'REST API', 'Məhsulları səhifə-səhifə (pagination) qaytarmaq üçün ən uyğun URL hansıdır?', '["POST /getProducts", "GET /products/page/2/limit/20/get", "GET /products-page-2", "GET /products?page=2&limit=20"]', 'GET /products?page=2&limit=20'),
('backend', 'REST API', 'REST qaydalarına ən uyğun endpoint hansıdır?', '["GET /users/15/orders", "GET /getUserOrders?id=15", "GET /user_orders_15", "POST /users/15/getOrders"]', 'GET /users/15/orders'),
('backend', 'REST API', 'Email formatı səhv göndərilib. Hansı status kodu qaytarılmalıdır?', '["200 OK", "400 Bad Request", "500 Internal Server Error", "404 Not Found"]', '400 Bad Request'),
('backend', 'Veb təhlükəsizliyi', 'İstifadəçi şifrələri bazada necə saxlanmalıdır?', '["Açıq mətn kimi, amma baza şifrələnərək", "bcrypt və ya argon2 ilə hash edilərək", "Base64 ilə kodlaşdırılaraq", "MD5 ilə hash edilərək"]', 'bcrypt və ya argon2 ilə hash edilərək'),
('backend', 'Veb təhlükəsizliyi', 'JWT token-in payload hissəsi haqqında hansı fikir doğrudur?', '["Payload-ı dəyişmək mümkün olmadığı üçün imzanı yoxlamağa ehtiyac yoxdur", "Payload şifrələnmir, hər kəs oxuya bilər, ona görə gizli məlumat yazılmamalıdır", "Payload yalnız serverdə saxlanılır", "Payload şifrələnir, istənilən məlumatı yazmaq olar"]', 'Payload şifrələnmir, hər kəs oxuya bilər, ona görə gizli məlumat yazılmamalıdır'),
('backend', 'Veb təhlükəsizliyi', 'İstifadəçinin şərhi səhifədə innerHTML ilə göstərilir və içində <script> var. Bu hansı hücumdur?', '["XSS (Cross-Site Scripting)", "SQL injection (SQLi)", "CSRF (Cross-Site Request Forgery)", "Clickjacking (UI redressing)"]', 'XSS (Cross-Site Scripting)'),
('backend', 'Veb təhlükəsizliyi', 'Login endpoint-inə saniyədə yüzlərlə şifrə cəhdi gəlir. Ən uyğun qoruma hansıdır?', '["Serveri yenidən başlatmaq", "Rate limiting (sorğu sayını məhdudlaşdırmaq)", "Şifrələrin minimum uzunluğunu artırmaq", "HTTPS-i söndürmək"]', 'Rate limiting (sorğu sayını məhdudlaşdırmaq)'),
('backend', 'Veb təhlükəsizliyi', 'API açarları və bazanın şifrəsi harada saxlanılmalıdır?', '["Verilənlər bazasının öz cədvəlində", "Frontend-də, minify edilmiş kodun içində", "Repo-dakı config.json faylında", "Mühit dəyişənlərində (.env), repoya salmadan"]', 'Mühit dəyişənlərində (.env), repoya salmadan'),
('backend', 'Veb təhlükəsizliyi', 'Login uğursuz olanda hansı mesaj daha təhlükəsizdir?', '["\"Bu email bazada yoxdur\"", "\"Email düzgündür, şifrə yanlışdır\"", "Xətanın tam stack trace-i", "\"Email və ya şifrə yanlışdır\""]', '"Email və ya şifrə yanlışdır"'),
('uiux', 'UI əsasları', 'Vizual iyerarxiya yaratmaq üçün ən təsirli vasitələr hansılardır?', '["Yalnız animasiya", "Bütün elementləri eyni ölçüdə etmək", "Mümkün qədər çox şrift növü", "Ölçü, rəng kontrastı və boşluq"]', 'Ölçü, rəng kontrastı və boşluq'),
('uiux', 'UI əsasları', 'Mobil tətbiqdə toxunulan düymənin tövsiyə olunan minimum ölçüsü təxminən nə qədərdir?', '["24×24 pt (təxminən 32×32 dp)", "44×44 pt (təxminən 48×48 dp)", "32×32 pt (təxminən 36×36 dp)", "64×64 pt (təxminən 80×80 dp)"]', '44×44 pt (təxminən 48×48 dp)'),
('uiux', 'UI əsasları', '8pt grid sistemi nə üçün istifadə olunur?', '["Ekranı bərabər genişlikdə 8 sütuna bölmək üçün", "Boşluqları və ölçüləri 8-in misilləri ilə ardıcıl qurmaq üçün", "Bütün mətnlərin minimum ölçüsünü 8pt etmək üçün", "İkonları 8×8 piksellik şəbəkədə çəkmək üçün"]', 'Boşluqları və ölçüləri 8-in misilləri ilə ardıcıl qurmaq üçün'),
('uiux', 'UI əsasları', 'Formada xəta mesajı harada göstərilməlidir?', '["Xəta göstərilməməlidir, sahə sadəcə təmizlənməlidir", "Müvafiq sahənin yanında (adətən altında)", "Yalnız popup pəncərədə", "Yalnız səhifənin ən aşağısında"]', 'Müvafiq sahənin yanında (adətən altında)'),
('uiux', 'UI əsasları', 'Primary və secondary düymələr arasındakı fərq nədir?', '["Primary yalnız mobil versiyada istifadə olunur", "Secondary həmişə qırmızı olur", "Primary əsas hərəkət üçündür və vizual olaraq daha qabarıqdır", "Heç bir fərq yoxdur"]', 'Primary əsas hərəkət üçündür və vizual olaraq daha qabarıqdır'),
('uiux', 'UI əsasları', 'Siyahı boşdur (empty state). Ən yaxşı yanaşma hansıdır?', '["Niyə boş olduğunu izah edib növbəti addımı təklif etmək", "Səhifəni avtomatik olaraq ana səhifəyə yönləndirmək", "Ekranda yalnız \"Məlumat yoxdur\" yazısını göstərmək", "Boşluğu doldurmaq üçün nümunə (saxta) məlumat göstərmək"]', 'Niyə boş olduğunu izah edib növbəti addımı təklif etmək'),
('uiux', 'UX araşdırma', 'İstifadəçi müsahibəsində hansı sual daha düzgündür?', '["\"Bu funksiya sizə lazımdırmı?\"", "\"Bizim tətbiqi bəyənərdiniz, elə deyilmi?\"", "\"Son dəfə onlayn kurs seçəndə necə qərar verdiniz?\"", "\"Bunun üçün neçə manat ödəyərdiniz?\""]', '"Son dəfə onlayn kurs seçəndə necə qərar verdiniz?"'),
('uiux', 'UX araşdırma', 'Usability testində əsas problemlərin çoxunu tapmaq üçün adətən neçə iştirakçı kifayət edir?', '["Ən azı 50", "1", "Təxminən 5", "100-dən çox"]', 'Təxminən 5'),
('uiux', 'UX araşdırma', 'Persona nədir?', '["Araşdırmaya əsaslanan, hədəf istifadəçini təmsil edən obraz", "Komandanın təsəvvür etdiyi ideal istifadəçinin təsviri", "Reklam kampaniyası üçün seçilmiş məşhur simanın obrazı", "Ən çox gəlir gətirən real müştərinin ətraflı profili"]', 'Araşdırmaya əsaslanan, hədəf istifadəçini təmsil edən obraz'),
('uiux', 'UX araşdırma', 'Kəmiyyət (quantitative) və keyfiyyət (qualitative) araşdırma arasındakı fərq nədir?', '["Kəmiyyət \"nə qədər?\", keyfiyyət isə \"niyə?\" sualına cavab verir", "Keyfiyyət araşdırması yalnız rəqəmlərlə işləyir", "Heç bir fərq yoxdur", "Kəmiyyət araşdırması yalnız müsahibədir"]', 'Kəmiyyət "nə qədər?", keyfiyyət isə "niyə?" sualına cavab verir'),
('uiux', 'UX araşdırma', 'User journey map nəyi göstərir?', '["Layihənin mərhələlərini və hər mərhələnin son tarixlərini", "Saytdakı bütün səhifələrin bir-biri ilə əlaqəsini (sayt xəritəsini)", "İstifadəçinin məqsədə çatana qədər keçdiyi addımları, hisslərini və problemlərini", "İstifadəçilərin saytda keçirdiyi orta vaxtın statistikasını"]', 'İstifadəçinin məqsədə çatana qədər keçdiyi addımları, hisslərini və problemlərini'),
('uiux', 'UX araşdırma', 'A/B testin məqsədi nədir?', '["Saytın iki fərqli brauzerdə eyni göründüyünü yoxlamaq", "İki versiyanı real istifadəçilərdə müqayisə edib nəticəni ölçmək", "İki dizayn variantını komandada səsverməyə qoyub seçmək", "Yeni versiyanı əvvəl test, sonra canlı serverdə yoxlamaq"]', 'İki versiyanı real istifadəçilərdə müqayisə edib nəticəni ölçmək'),
('uiux', 'Figma', 'Bir düyməni 30 ekranda istifadə edirsən və dizaynını bir yerdən dəyişmək istəyirsən. Nə istifadə etməlisən?', '["Group və duplicate", "Section və slice", "Component və instance", "Frame və clip content"]', 'Component və instance'),
('uiux', 'Figma', 'Auto Layout nə edir?', '["Dizayndan avtomatik olaraq HTML və CSS kodu yaradır", "Elementləri layout grid-in sütunlarına avtomatik yapışdırır", "Elementləri məzmuna görə avtomatik düzür və ölçüləndirir (CSS flexbox kimi)", "Seçilmiş frame-i bütün ekran ölçülərinə avtomatik uyğunlaşdırır"]', 'Elementləri məzmuna görə avtomatik düzür və ölçüləndirir (CSS flexbox kimi)'),
('uiux', 'Figma', 'Düymənin default, hover və disabled vəziyyətlərini bir komponentdə saxlamaq üçün nə istifadə olunur?', '["Variants", "Plugins", "Layers", "Pages"]', 'Variants'),
('uiux', 'Figma', 'Rəng və şriftləri komanda üçün təkrar istifadə oluna bilən etmək üçün nə etmək lazımdır?', '["Hər dəfə HEX kodunu əllə yazmaq", "Styles və ya Variables yaratmaq", "Palitranın ekran şəklini çəkmək", "Rəngləri bir qrupa salmaq"]', 'Styles və ya Variables yaratmaq'),
('uiux', 'Figma', 'Developer-ə dizaynı təhvil verərkən ölçüləri və CSS dəyərlərini göstərmək üçün Figma-da hansı rejim var?', '["Presentation view", "Branching", "Prototype mode", "Dev Mode"]', 'Dev Mode'),
('uiux', 'Figma', 'Constraints nə üçündür?', '["Komponentin hansı xüsusiyyətlərinin dəyişə biləcəyini təyin etmək üçün", "Frame ölçüsü dəyişəndə elementin necə yerləşəcəyini təyin etmək üçün", "Faylı başqa istifadəçilərin redaktəsindən qorumaq üçün", "Mətnin minimum və maksimum şrift ölçüsünü məhdudlaşdırmaq üçün"]', 'Frame ölçüsü dəyişəndə elementin necə yerləşəcəyini təyin etmək üçün'),
('uiux', 'Rəng və tipoqrafiya', 'WCAG AA standartına görə adi mətn üçün minimum kontrast nisbəti nə qədərdir?', '["1.5:1", "2:1", "10:1", "4.5:1"]', '4.5:1'),
('uiux', 'Rəng və tipoqrafiya', '60-30-10 qaydası nədir?', '["Əsas rəng 60%, ikinci rəng 30%, vurğu rəngi 10%", "Rənglər bir-birindən 60, 30 və 10 dərəcə fərqlənməlidir", "Ekranın 60%-i boş qalmalıdır", "Şriftlər 60, 30 və 10 px olmalıdır"]', 'Əsas rəng 60%, ikinci rəng 30%, vurğu rəngi 10%'),
('uiux', 'Rəng və tipoqrafiya', 'Bədən mətni üçün optimal sətir uzunluğu təxminən nə qədərdir?', '["10–20 simvol", "45–75 simvol", "Sətir uzunluğunun əhəmiyyəti yoxdur", "150–200 simvol"]', '45–75 simvol'),
('uiux', 'Rəng və tipoqrafiya', 'Bir interfeysdə adətən neçə şrift ailəsi istifadə etmək tövsiyə olunur?', '["Hər bölmə üçün ayrıca şrift", "Ən azı 4", "5–6", "1–2"]', '1–2'),
('uiux', 'Rəng və tipoqrafiya', 'Uğur, xəbərdarlıq və xəta üçün yalnız rəngdən (yaşıl, sarı, qırmızı) istifadə etmək niyə kifayət deyil?', '["Bu rənglər qaranlıq rejimdə tamamilə fərqli göründüyü üçün", "Brend rəngləri ilə toqquşduğu üçün dizayn sistemində qadağandır", "Rəng korluğu olanlar fərqi görməyə bilər, ona görə ikon və ya mətn də lazımdır", "Kifayətdir, çünki bu rənglər bütün mədəniyyətlərdə eyni mənanı verir"]', 'Rəng korluğu olanlar fərqi görməyə bilər, ona görə ikon və ya mətn də lazımdır'),
('uiux', 'Rəng və tipoqrafiya', 'Bədən mətni üçün tövsiyə olunan sətir aralığı (line-height) adətən nə qədərdir?', '["3.0", "1.0-dan az", "0.8", "1.4–1.6"]', '1.4–1.6'),
('uiux', 'Prototipləmə', 'Low-fidelity və high-fidelity prototip arasındakı fərq nədir?', '["High-fi sürətli eskizdir, low-fi isə son məhsula yaxın detallı versiyadır", "Low-fi yalnız mobil, high-fi isə yalnız desktop ekranlar üçün hazırlanır", "Low-fi rəngsiz son dizayndır, high-fi isə kodla yazılmış versiyadır", "Low-fi sürətli və sadə eskizdir, high-fi isə son məhsula yaxın detallı versiyadır"]', 'Low-fi sürətli və sadə eskizdir, high-fi isə son məhsula yaxın detallı versiyadır'),
('uiux', 'Prototipləmə', 'Wireframe mərhələsində əsas diqqət nəyə yönəlməlidir?', '["Rəng palitrasına və şəkillərin seçiminə", "Struktura, məzmunun yerləşməsinə və axına", "Şrift ailəsinə və brend elementlərinə", "Animasiyalara və keçid effektlərinə"]', 'Struktura, məzmunun yerləşməsinə və axına'),
('uiux', 'Prototipləmə', 'Figma prototipində ekranlar arası keçid üçün nə qurulur?', '["Variable mode (məs. Light → Dark)", "Interaction (məs. On click → Navigate to)", "Component property (məs. Boolean → Show)", "Layout grid (məs. Columns → Stretch)"]', 'Interaction (məs. On click → Navigate to)'),
('uiux', 'Prototipləmə', 'Prototipi istifadəçilərlə test etməyin əsas məqsədi nədir?', '["Rənglərin ekranda düzgün göründüyünü yoxlamaq", "Kod yazmazdan əvvəl problemləri ucuz və tez tapmaq", "Dizaynerin işinin keyfiyyətini qiymətləndirmək", "İnvestorlara son məhsulu nümayiş etdirmək"]', 'Kod yazmazdan əvvəl problemləri ucuz və tez tapmaq'),
('uiux', 'Prototipləmə', 'User flow diaqramı nəyi göstərir?', '["Saytın bütün səhifələrinin iyerarxik siyahısını (sitemap)", "Komanda üzvləri arasında tapşırıqların bölgüsünü və statusunu", "Frontend ilə backend arasındakı API sorğularının ardıcıllığını", "İstifadəçinin tapşırığı yerinə yetirmək üçün keçdiyi ekranları və qərar nöqtələrini"]', 'İstifadəçinin tapşırığı yerinə yetirmək üçün keçdiyi ekranları və qərar nöqtələrini'),
('uiux', 'Prototipləmə', 'Məhsul dizaynında MVP nə deməkdir?', '["Bütün planlaşdırılan funksiyaları bir dəfəyə hazırlayıb təqdim etmək", "Yalnız vizual dizaynı hazırlayıb kodu sonraya saxlamaq", "Əsas problemi həll edən ən sadə versiyanı tez yaradıb yoxlamaq", "Məhsulu ilk istifadəçilərə pulsuz paylayıb rəy toplamaq"]', 'Əsas problemi həll edən ən sadə versiyanı tez yaradıb yoxlamaq'),
