('data', 'Excel', '=SUMIF(A:A; "Bakı"; B:B) formulu nə edir?', '["A sütununda \"Bakı\" olan sətirlərin B sütunundakı dəyərlərini toplayır", "A sütunu \"Bakı\" olan ilk sətrin B sütunundakı dəyərini qaytarır", "B sütununda \"Bakı\" olan sətirlərin A sütunundakı dəyərlərini toplayır", "A sütununda \"Bakı\" sözünün neçə dəfə təkrarlandığını hesablayır"]', 'A sütununda "Bakı" olan sətirlərin B sütunundakı dəyərlərini toplayır'),
('data', 'Excel', 'Formulu kopyalayanda hüceyrə istinadının dəyişməməsi üçün nə edilir?', '["F9 düyməsi basılır", "Formul mətn kimi yazılır", "Nisbi istinad yazılır (A1)", "Mütləq istinad yazılır ($A$1)"]', 'Mütləq istinad yazılır ($A$1)'),
('data', 'SQL ilə analiz', 'Hər kateqoriya üzrə ümumi satışı hesablamaq üçün nə istifadə olunur?', '["SUM(amount) + GROUP BY category", "SUM(DISTINCT category) + WHERE", "SUM(amount) + ORDER BY category", "COUNT(amount) + GROUP BY category"]', 'SUM(amount) + GROUP BY category'),
('data', 'SQL ilə analiz', 'Ən çox satış edən 5 məhsulu tapmaq üçün sorğu necə bitməlidir?', '["ORDER BY total ASC LIMIT 5", "ORDER BY total DESC LIMIT 5", "GROUP BY 5", "WHERE total = 5"]', 'ORDER BY total DESC LIMIT 5'),
